class Solution {
public:
    bool divisorGame(int n) {
        vector<bool> win(n + 1, false);
        for (int i = 2; i <= n; i++) {
            for (int x = 1; x < i; x++) {
                if (i % x == 0 && !win[i - x]) {
                    win[i] = true;
                    break;
                }
            }
        }
        return win[n];
    }
};
